AOD_GAMEMODE="classic"import("winconditions/aod.scar")function Mission_AOD_Start()if(not Event_IsAnyRunning())then Rule_RemoveMe()if(not SETTINGS.IsInitialized()or#(SETTINGS.GetSetting("WAVE_SETUP"))==0)then return end SPAWN_TEST_DUMMY_ENTITY=Entity_Create(BP_GetEntityBlueprint("assault_engineer_mp"),AIPlayer1,World_Pos(0,0,0),World_Pos(0,0,0))Game_FadeToBlack(FADE_OUT,0)Game_FadeToBlack(FADE_IN,0.5)UnsavedTimeRule_AddOneShot(StartupStatsMessage,3.0,500)Rule_AddInterval(_CheckAIending,1,1000)CURRENT_WAVE_GROUP=SGroup_CreateIfNotFound("AOD_current_wave_group")WAITING_FOR_NEXT_WAVE=true Timer_Start(1,SETTINGS.GetSetting("START_TIME"))Timer_Start(2,1)Timer_Start(3,1)Rule_AddInterval(_SpawnWaves,0.5,999)Rule_AddInterval(_SpawnEvents,0.5,999)Rule_AddInterval(_INCREASE_WAVE_TIMER,0.2,999)Rule_AddInterval(_CheckWin,1.0,999)Rule_AddInterval(_SendOrdersToBattleSquads,1,100)Rule_AddInterval(_UpgradeParadrops,1,100)Objective_Start(OBJECTIVES["countdown"],true)if(SETTINGS.GetSetting("LOSE_CONDITION")=="overrun"and SETTINGS.GetSetting("DIFFICULTY")["units_allowed_to_pass"]~=nil and Util_GetDifficultyValue(SETTINGS.GetSetting("DIFFICULTY")["units_allowed_to_pass"])>0)then Objective_Start(OBJECTIVES["units_allowed_to_pass"],true)Objective_UpdateText(OBJECTIVES["units_allowed_to_pass"],Loc_FormatText(Util_CreateLocId(1337004),Loc_ConvertNumber(Util_GetDifficultyValue(SETTINGS.GetSetting("DIFFICULTY")["units_allowed_to_pass"])-1)),nil,true)
